def center_based_shift(grid, center_col=10):
    from collections import deque
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and not visited[r][c]:
                queue = deque([(r,c)])
                visited[r][c] = True
                comp = []
                while queue:
                    cr, cc = queue.popleft()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == 0 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr,nc))
                components.append(comp)

    new_grid = [[9]*cols for _ in range(rows)]
    for comp in components:
        # Use center column of component to decide
        c_cols = [cc for rc, cc in comp]
        avg_c = sum(c_cols) / len(c_cols)

        if avg_c < center_col:
            # Left of center - shift right 1
            for r, c in comp:
                new_c = c + 1
                if new_c < cols:
                    new_grid[r][new_c] = 0
        else:
            # Right of center or touching center - stay put
            for r, c in comp:
                new_grid[r][c] = 0

    return new_grid

