def conditional_row_shift(grid):
    rows, cols = len(grid), len(grid[0])
    output = [[9]*cols for _ in range(rows)]

    for r in range(rows):
        # Find the columns with 0s in this row
        zero_cols = [c for c in range(cols) if grid[r][c] == 0]

        if grid[r][0] == 0:
            # Row starts with 0: shift right by 0 (keep in place)
            for c in zero_cols:
                output[r][c] = 0
        else:
            # Row doesn't start with 0: shift left by 1
            for c in zero_cols:
                new_c = c - 1
                if 0 <= new_c < cols:
                    output[r][new_c] = 0

    return output

