# For each row, fill the gaps between consecutive 0-blocks
def fill_between_blocks(grid):
    rows, cols = len(grid), len(grid[0])
    output = [[9]*cols for _ in range(rows)]

    for r in range(rows):
        # Find all zero blocks
        blocks = []
        i = 0
        while i < cols:
            if grid[r][i] == 0:
                start = i
                while i < cols and grid[r][i] == 0:
                    i += 1
                end = i - 1
                blocks.append((start, end))
            else:
                i += 1

        # Fill gaps between blocks if multiple blocks exist
        if len(blocks) > 1:
            for j in range(len(blocks) - 1):
                # Fill the gap between block j and block j+1
                gap_start = blocks[j][1] + 1
                gap_end = blocks[j+1][0] - 1
                if gap_start <= gap_end:
                    for c in range(gap_start, gap_end + 1):
                        output[r][c] = 0

        # But keep the original blocks
        for start, end in blocks:
            for c in range(start, end + 1):
                output[r][c] = 0

    return output

