# Try: shift LEFT each row's pattern, then fill small gaps
def shift_and_fill_left(grid, shift_amount=1, max_gap=2):
    rows, cols = len(grid), len(grid[0])
    output = [[9]*cols for _ in range(rows)]

    for r in range(rows):
        # First, find all zero blocks in original row
        blocks = []
        i = 0
        while i < cols:
            if grid[r][i] == 0:
                start = i
                while i < cols and grid[r][i] == 0:
                    i += 1
                end = i - 1
                blocks.append((start, end))
            else:
                i += 1

        # Shift all blocks left by shift_amount
        new_blocks = [(max(0, start - shift_amount), end - shift_amount) for start, end in blocks if end - shift_amount >= 0]

        # Now fill small gaps (but only if blocks are close)
        output_r = []
        for start, end in new_blocks:
            output_r.extend([0]*(end - start + 1))

        # Check for gaps and fill small ones
        i = 0
        while i < len(output_r):
            if output_r[i] == 0:
                start = i
                while i < len(output_r) and output_r[i] == 0:
                    i += 1
                end = i - 1
                output_r[i] = 9
            else:
                i += 1

        # Re-assemble
        blocks_after = []
        i = 0
        while i < len(output_r):
            if output_r[i] == 0:
                start = i
                while i < len(output_r) and output_r[i] == 0:
                    i += 1
                end = i - 1
                blocks_after.append((start, end))
            else:
                i += 1

        # Fill gaps
        if len(blocks_after) > 1:
            for j in range(len(blocks_after) - 1):
                gap_start = blocks_after[j][1] + 1
                gap_end = blocks_after[j+1][0] - 1
                gap_size = gap_end - gap_start + 1

                if 1 <= gap_size <= max_gap:
                    for c in range(gap_start, gap_end + 1):
                        output_r[c] = 0

        for c, val in enumerate(output_r):
            output[r][c] = val

    return output

