from collections import deque

def shift_right_if_left_half(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and not visited[r][c]:
                queue = deque([(r,c)])
                visited[r][c] = True
                comp = []
                while queue:
                    cr, cc = queue.popleft()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == 0 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr,nc))
                components.append(comp)

    new_grid = [[9]*cols for _ in range(rows)]
    for comp in components:
        # Check if any pixel is in left half (col < 10)
        has_left = any(c < 10 for r, c in comp)
        has_right = any(c >= 10 for r, c in comp)

        if has_left:
            # Contains left half - shift whole component right by 1
            for r, c in comp:
                nc = c + 1
                if nc < cols:
                    new_grid[r][nc] = 0
        else:
            # Entirely in right half - stay in place
            for r, c in comp:
                new_grid[r][c] = 0

    return new_grid

